// @vitest-environment node
import { describe, it, expect } from 'vitest';
import {
  getActiveStreak,
  isStreakProtectedByFreeze,
  applyStreakUpdate,
  applySettlement,
  settleStreak,
  STREAK_FREEZE_INTERVAL,
  STREAK_FREEZE_MAX,
} from '../lib/streak';
import { createNewProfile, importProfile } from '../lib/storage';
import type { UserProfile } from '../types';

function makeProfile(overrides: Partial<UserProfile>): UserProfile {
  return { ...createNewProfile('Test'), ...overrides };
}

function settleOn(profile: UserProfile, today: string): UserProfile {
  return applySettlement(profile, settleStreak(profile, today));
}

describe('getActiveStreak', () => {
  it('renvoie 0 quand aucune séance n\'a jamais été complétée', () => {
    const profile = makeProfile({ lastSessionDate: null, currentStreak: 0 });
    expect(getActiveStreak(profile, '2026-04-30')).toBe(0);
  });

  it('renvoie la valeur stockée si la dernière séance est aujourd\'hui', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-30', currentStreak: 5 });
    expect(getActiveStreak(profile, '2026-04-30')).toBe(5);
  });

  it('renvoie la valeur stockée si la dernière séance est hier (la série peut encore être prolongée)', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-29', currentStreak: 3 });
    expect(getActiveStreak(profile, '2026-04-30')).toBe(3);
  });

  it('renvoie 0 si la dernière séance date d\'avant-hier sans gel disponible (série rompue)', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 7, streakFreezes: 0 });
    expect(getActiveStreak(profile, '2026-04-30')).toBe(0);
  });

  it('renvoie la valeur stockée si la dernière séance date d\'avant-hier ET qu\'un gel est disponible (série protégée)', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 7, streakFreezes: 1 });
    expect(getActiveStreak(profile, '2026-04-30')).toBe(7);
  });

  it('renvoie la valeur stockée si 2 jours manqués sont couverts par 2 gels (série protégée)', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-27', currentStreak: 12, streakFreezes: 2 });
    expect(getActiveStreak(profile, '2026-04-30')).toBe(12);
  });

  it('renvoie 0 si 2 jours manqués mais 1 seul gel (couverture insuffisante)', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-27', currentStreak: 12, streakFreezes: 1 });
    expect(getActiveStreak(profile, '2026-04-30')).toBe(0);
  });

  it('renvoie 0 si 3 jours manqués, même avec le cap de 2 gels', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-26', currentStreak: 12, streakFreezes: 2 });
    expect(getActiveStreak(profile, '2026-04-30')).toBe(0);
  });

  it('renvoie 0 si la dernière séance date d\'il y a une semaine', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-23', currentStreak: 12 });
    expect(getActiveStreak(profile, '2026-04-30')).toBe(0);
  });
});

describe('isStreakProtectedByFreeze', () => {
  it('est faux si jamais joué', () => {
    const profile = makeProfile({ lastSessionDate: null, streakFreezes: 2 });
    expect(isStreakProtectedByFreeze(profile, '2026-04-30')).toBe(false);
  });

  it('est faux si la dernière séance est aujourd\'hui', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-30', currentStreak: 5, streakFreezes: 1 });
    expect(isStreakProtectedByFreeze(profile, '2026-04-30')).toBe(false);
  });

  it('est faux si la dernière séance est hier (série naturellement active)', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-29', currentStreak: 5, streakFreezes: 1 });
    expect(isStreakProtectedByFreeze(profile, '2026-04-30')).toBe(false);
  });

  it('est vrai si la dernière séance est avant-hier ET qu\'un gel est disponible', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 5, streakFreezes: 1 });
    expect(isStreakProtectedByFreeze(profile, '2026-04-30')).toBe(true);
  });

  it('reste vrai une fois le gel déjà débité par le règlement', () => {
    // État d'un profil rechargé le lendemain du règlement : le gel est parti,
    // mais la série est bien protégée jusqu'à la prochaine séance.
    const profile = makeProfile({
      lastSessionDate: '2026-04-28',
      currentStreak: 5,
      streakFreezes: 0,
      freezeSettledDate: '2026-04-29',
    });
    expect(isStreakProtectedByFreeze(profile, '2026-04-30')).toBe(true);
  });

  it('est vrai si 2 jours manqués sont couverts par 2 gels', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-27', currentStreak: 5, streakFreezes: 2 });
    expect(isStreakProtectedByFreeze(profile, '2026-04-30')).toBe(true);
  });

  it('est faux si 2 jours manqués mais 1 seul gel (couverture insuffisante)', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-27', currentStreak: 5, streakFreezes: 1 });
    expect(isStreakProtectedByFreeze(profile, '2026-04-30')).toBe(false);
  });

  it('est faux si la dernière séance est avant-hier mais aucun gel', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 5, streakFreezes: 0 });
    expect(isStreakProtectedByFreeze(profile, '2026-04-30')).toBe(false);
  });
});

describe('settleStreak — débit des gels au jour manqué', () => {
  it('ne touche à rien tant que le jour en cours n\'est pas écoulé', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-29', currentStreak: 5, streakFreezes: 2 });
    const r = settleStreak(profile, '2026-04-30');
    expect(r.changed).toBe(false);
    expect(r.streakFreezes).toBe(2);
    expect(r.currentStreak).toBe(5);
  });

  it('débite un gel dès le lendemain du jour manqué, sans attendre la séance', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 5, streakFreezes: 2 });
    const r = settleStreak(profile, '2026-04-30');
    expect(r.changed).toBe(true);
    expect(r.streakFreezes).toBe(1);
    expect(r.currentStreak).toBe(5);
    expect(r.freezeSettledDate).toBe('2026-04-29');
  });

  it('est idempotent : un 2e passage le même jour ne redébite pas', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 5, streakFreezes: 2 });
    const second = settleStreak(settleOn(profile, '2026-04-30'), '2026-04-30');
    expect(second.changed).toBe(false);
    expect(second.streakFreezes).toBe(1);
  });

  it('débite un gel de plus au fil des jours manqués successifs', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 5, streakFreezes: 2 });
    const day2 = settleStreak(settleOn(profile, '2026-04-30'), '2026-05-01');
    expect(day2.streakFreezes).toBe(0);
    expect(day2.currentStreak).toBe(5);
    expect(day2.freezeSettledDate).toBe('2026-04-30');
  });

  it('casse la série une fois les gels épuisés', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 5, streakFreezes: 2 });
    const day2 = settleOn(settleOn(profile, '2026-04-30'), '2026-05-01');
    const day3 = settleStreak(day2, '2026-05-02');
    expect(day3.currentStreak).toBe(0);
    expect(day3.streakFreezes).toBe(0);
  });

  // Un gel dépensé l'est pour de bon : sans ça, le solde dépendrait du fait
  // d'avoir ouvert l'app pendant l'absence.
  it('donne le même solde que le règlement soit fait jour par jour ou en un bloc', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 5, streakFreezes: 2 });
    const dayByDay = settleOn(
      settleOn(settleOn(profile, '2026-04-30'), '2026-05-01'),
      '2026-05-02',
    );
    const inOneGo = settleOn(profile, '2026-05-02');
    expect(inOneGo.currentStreak).toBe(dayByDay.currentStreak);
    expect(inOneGo.streakFreezes).toBe(dayByDay.streakFreezes);
  });

  it('ne dépense plus rien une fois la série cassée', () => {
    const profile = makeProfile({
      lastSessionDate: '2026-04-20',
      currentStreak: 0,
      streakFreezes: 2,
    });
    const r = settleStreak(profile, '2026-04-30');
    expect(r.changed).toBe(false);
    expect(r.streakFreezes).toBe(2);
  });

  it('ne débite rien si l\'horloge recule (changement de fuseau)', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-30', currentStreak: 5, streakFreezes: 2 });
    const r = settleStreak(profile, '2026-04-28');
    expect(r.changed).toBe(false);
    expect(r.streakFreezes).toBe(2);
  });
});

describe('applyStreakUpdate', () => {
  it('démarre la série à 1 quand jamais joué', () => {
    const profile = makeProfile({ lastSessionDate: null, currentStreak: 0, streakFreezes: 0 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(1);
    expect(r.streakFreezes).toBe(0);
    expect(r.freezeJustUsed).toBe(false);
    expect(r.freezeJustEarned).toBe(false);
  });

  it('ne touche à rien sur une séance le même jour', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-30', currentStreak: 4, streakFreezes: 1 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(4);
    expect(r.streakFreezes).toBe(1);
    expect(r.freezeJustUsed).toBe(false);
    expect(r.freezeJustEarned).toBe(false);
  });

  it('incrémente la série si la séance précédente est hier', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-29', currentStreak: 3, streakFreezes: 0 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(4);
    expect(r.streakFreezes).toBe(0);
    expect(r.freezeJustUsed).toBe(false);
    expect(r.freezeJustEarned).toBe(false);
  });

  it('attribue un gel quand la série atteint un multiple de 7', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-29', currentStreak: 6, streakFreezes: 0 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(7);
    expect(r.streakFreezes).toBe(1);
    expect(r.freezeJustEarned).toBe(true);
    expect(r.freezeJustUsed).toBe(false);
  });

  it('n\'attribue pas de gel quand le cap est atteint', () => {
    const profile = makeProfile({
      lastSessionDate: '2026-04-29',
      currentStreak: 13,
      streakFreezes: STREAK_FREEZE_MAX,
    });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(14);
    expect(r.streakFreezes).toBe(STREAK_FREEZE_MAX);
    expect(r.freezeJustEarned).toBe(false);
  });

  it('consomme un gel et préserve la série après 1 jour manqué', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 5, streakFreezes: 1 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(6);
    expect(r.streakFreezes).toBe(0);
    expect(r.freezeJustUsed).toBe(true);
    expect(r.freezeJustEarned).toBe(false);
  });

  it('reset la série à 1 après 1 jour manqué si pas de gel', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 5, streakFreezes: 0 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(1);
    expect(r.streakFreezes).toBe(0);
    expect(r.freezeJustUsed).toBe(false);
  });

  it('consomme 2 gels et préserve la série après 2 jours manqués', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-27', currentStreak: 10, streakFreezes: 2 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(11);
    expect(r.streakFreezes).toBe(0);
    expect(r.freezeJustUsed).toBe(true);
    expect(r.freezeJustEarned).toBe(false);
  });

  it('reset la série à 1 après 2 jours manqués avec 1 seul gel (couverture insuffisante)', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-27', currentStreak: 10, streakFreezes: 1 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(1);
    // Le gel a bien servi à couvrir le 1er jour manqué avant que la série casse.
    expect(r.streakFreezes).toBe(0);
    expect(r.freezeJustUsed).toBe(false);
  });

  it('reset la série à 1 après 3 jours manqués, même avec le cap de 2 gels', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-26', currentStreak: 10, streakFreezes: 2 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(1);
    expect(r.streakFreezes).toBe(0);
    expect(r.freezeJustUsed).toBe(false);
  });

  it('brûle les gels jusqu\'à épuisement quand la série casse vraiment', () => {
    const profile = makeProfile({ lastSessionDate: '2026-04-20', currentStreak: 8, streakFreezes: 2 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(1);
    expect(r.streakFreezes).toBe(0);
  });

  it('peut consommer un gel ET en gagner un dans le même tour (cas limite)', () => {
    // série à 6, +2 jours, gel disponible : consomme → série passe à 7 → multiple de 7 → +1 gel
    const profile = makeProfile({ lastSessionDate: '2026-04-28', currentStreak: 6, streakFreezes: 1 });
    const r = applyStreakUpdate(profile, '2026-04-30');
    expect(r.currentStreak).toBe(7);
    expect(r.streakFreezes).toBe(1);
    expect(r.freezeJustUsed).toBe(true);
    expect(r.freezeJustEarned).toBe(true);
  });

  it(`STREAK_FREEZE_INTERVAL vaut 7 (vérifie le contrat documenté)`, () => {
    expect(STREAK_FREEZE_INTERVAL).toBe(7);
  });
});

describe('migration : rétro-attribution des gels selon la série en cours', () => {
  function importLegacyProfile(currentStreak: number): UserProfile {
    const base = createNewProfile('Test');
    const { streakFreezes: _omit, ...rest } = base;
    return importProfile(JSON.stringify({ ...rest, currentStreak }))!;
  }

  it('série < 7 → aucun gel rétro-attribué', () => {
    expect(importLegacyProfile(0).streakFreezes).toBe(0);
    expect(importLegacyProfile(6).streakFreezes).toBe(0);
  });

  it('série 7..13 → 1 gel rétro-attribué', () => {
    expect(importLegacyProfile(7).streakFreezes).toBe(1);
    expect(importLegacyProfile(13).streakFreezes).toBe(1);
  });

  it('série 14+ → cap à 2 gels', () => {
    expect(importLegacyProfile(14).streakFreezes).toBe(2);
    expect(importLegacyProfile(30).streakFreezes).toBe(STREAK_FREEZE_MAX);
  });
});
